targets.expr:
sum by(provisionerId, workerType) (
  avg_over_time(fxci_queue_running_workers{
    provisionerId!~"^gecko.*",
    provisionerId!~".*k8s",
    provisionerId=~"$provisioner",
    workerType=~"$workerType",
  }[$__interval])
)

sum by(provisionerId, workerType) (
  avg_over_time(fxci_queue_workers_total{
    provisionerId!~"^gecko.*",
    provisionerId!~".*k8s",
    provisionerId=~"$provisioner",
    workerType=~"$workerType",
  }[$__interval])
  - 
  avg_over_time(fxci_queue_quarantined_workers{
    provisionerId!~"^gecko.*",
    provisionerId!~".*k8s",
    provisionerId=~"$provisioner",
    workerType=~"$workerType",
  }[$__interval])
)

sum by(provisionerId, workerType) (
  avg_over_time(fxci_queue_quarantined_workers{
    provisionerId!~"^gecko.*",
    provisionerId!~"k8s",
    provisionerId=~"$provisioner",
    workerType=~"$workerType",
  }[$__interval])
)
